// false — create it closed
var ready = new ManualResetEvent(false);
var next  = new AutoResetEvent(false);
var slots = new Semaphore(3, 3);  // 3 of 3 free

// open for everyone until Reset() is called
ready.Set();
// lets one WaitOne through and closes again
next.Set();

// take a slot (or sleep while there are none)
slots.WaitOne();
// returning it from another thread is fine
await Task.Run(() => slots.Release());

